package io.rift.cronos;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Separate app-private checkpoint DB. No credentials; never included in portable workspace backups. */
public final class ReceiptWatchStore extends SQLiteOpenHelper {
 public ReceiptWatchStore(Context context){super(context,"rift-receipt-watches.sqlite",null,1);}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE watches(id TEXT PRIMARY KEY,account TEXT NOT NULL,hash TEXT NOT NULL,created INTEGER NOT NULL,next INTEGER NOT NULL,attempts INTEGER NOT NULL,status TEXT NOT NULL,claim TEXT NOT NULL,report TEXT NOT NULL,note TEXT NOT NULL,UNIQUE(account,hash))");}
 @Override public void onUpgrade(SQLiteDatabase db,int from,int to){throw new IllegalStateException("Unsupported receipt-watch schema upgrade");}
 public void watch(String account,String hash,long now)throws Exception{WorkspacePolicy.account(account);hash=ReadPolicy.hash(hash);if(now<0)throw new IllegalArgumentException();SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{boolean existing;try(Cursor c=db.rawQuery("SELECT 1 FROM watches WHERE account=? AND hash=?",new String[]{account,hash})){existing=c.moveToFirst();}try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM watches",null)){c.moveToFirst();if(!existing&&c.getInt(0)>=WatchPolicy.MAX_WATCHES)throw new IllegalStateException("20 receipt watches maximum; remove older watches first");}ContentValues row=new ContentValues();row.put("id",UUID.randomUUID().toString());row.put("account",account);row.put("hash",hash);row.put("created",now);row.put("next",now);row.put("attempts",0);row.put("status","watching");row.put("claim","");row.put("report","{}");row.put("note","Best-effort receipt observation; no transaction will be sent");if(db.insertWithOnConflict("watches",null,row,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IllegalStateException("Receipt watch was not stored");db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void expire(long now){getWritableDatabase().execSQL("UPDATE watches SET status='expired',claim='',note='Observation window/attempt bound ended; inspect manually before retrying a value action' WHERE status='watching' AND (created>? OR created<=? OR attempts>=?)",new Object[]{now,now-WatchPolicy.MAX_AGE,WatchPolicy.MAX_ATTEMPTS});}
 public JSONObject claim(long now)throws Exception{SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{expire(now);JSONObject row=null;try(Cursor c=db.rawQuery("SELECT id,account,hash,created,next,attempts,status,claim,report,note FROM watches WHERE status='watching' AND next<=? ORDER BY next,id LIMIT 1",new String[]{Long.toString(now)})){if(c.moveToFirst())row=read(c);}if(row!=null){String claim=UUID.randomUUID().toString();int attempts=row.getInt("attempts")+1;ContentValues values=new ContentValues();values.put("claim",claim);values.put("attempts",attempts);values.put("next",WatchPolicy.next(now,attempts,false));db.update("watches",values,"id=? AND status='watching'",new String[]{row.getString("id")});row.put("claim",claim).put("attempts",attempts);}db.setTransactionSuccessful();return row;}finally{db.endTransaction();}}
 private JSONObject read(Cursor c)throws Exception{return new JSONObject().put("id",c.getString(0)).put("account",c.getString(1)).put("hash",c.getString(2)).put("created",c.getLong(3)).put("nextCheckNotBefore",c.getLong(4)).put("attempts",c.getInt(5)).put("status",c.getString(6)).put("claim",c.getString(7)).put("report",new JSONObject(c.getString(8))).put("note",c.getString(9));}
 public boolean complete(JSONObject claim,JSONObject report,String status,String note,long now,boolean error)throws Exception{if(!Arrays.asList("watching","observed-inclusion","needs-attention").contains(status)||note.length()>500||report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException("Invalid watch completion");ContentValues values=new ContentValues();values.put("status",status);values.put("claim","");values.put("report",report.toString());values.put("note",note);values.put("next",WatchPolicy.next(now,claim.getInt("attempts"),error));return getWritableDatabase().update("watches",values,"id=? AND claim=? AND status='watching'",new String[]{claim.getString("id"),claim.getString("claim")})==1;}
 public JSONArray list(String account)throws Exception{WorkspacePolicy.account(account);JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,account,hash,created,next,attempts,status,claim,report,note FROM watches WHERE account=? ORDER BY created DESC LIMIT 20",new String[]{account})){while(c.moveToNext()){JSONObject row=read(c);row.remove("claim");rows.put(row);}}return rows;}
 public int active(){try(Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM watches WHERE status='watching'",null)){c.moveToFirst();return c.getInt(0);}}
 public void clear(String account){WorkspacePolicy.account(account);getWritableDatabase().delete("watches","account=?",new String[]{account});}
 public void remove(String account,String hash){WorkspacePolicy.account(account);getWritableDatabase().delete("watches","account=? AND hash=?",new String[]{account,ReadPolicy.hash(hash)});}
}
